-- Degree Programs - Lot 7: deterministic results and credits. Run after migration 015.
do $$ begin create type public.academic_course_result_status as enum ('PENDING','PASSED','FAILED','RESIT_REQUIRED','EXEMPTED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_unit_result_status as enum ('PENDING','VALIDATED','COMPENSATED','PARTIALLY_VALIDATED','FAILED'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_semester_result_status as enum ('VALIDATED','PARTIALLY_VALIDATED','RESIT_REQUIRED','FAILED','PENDING_JURY'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_result_workflow_status as enum ('CALCULATED','SUBMITTED','VALIDATED','STALE'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_resit_status as enum ('ELIGIBLE','REGISTERED','COMPLETED','WAIVED','NOT_ELIGIBLE'); exception when duplicate_object then null; end $$;
do $$ begin create type public.academic_credit_level as enum ('COURSE','TEACHING_UNIT','SEMESTER','ACADEMIC_YEAR','PROGRAM'); exception when duplicate_object then null; end $$;

create table if not exists public.academic_course_results(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),course_id uuid not null references public.academic_courses(id),semester_id uuid not null references public.academic_semesters(id),course_enrollment_id uuid not null references public.academic_course_enrollments(id),
 continuous_assessment_score numeric(7,2),final_exam_score numeric(7,2),resit_score numeric(7,2),final_score numeric(7,2) not null check(final_score between 0 and 100),grade_letter text not null,credits_attempted numeric(7,2) not null,credits_earned numeric(7,2) not null,result_status public.academic_course_result_status not null,workflow_status public.academic_result_workflow_status not null default 'CALCULATED',calculation_version integer not null default 1,calculated_by uuid references public.profiles(id),calculated_at timestamptz not null default now(),submitted_by uuid references public.profiles(id),submitted_at timestamptz,validated_by uuid references public.profiles(id),validated_at timestamptz,updated_at timestamptz not null default now(),unique(student_id,course_id,semester_id),check(credits_earned between 0 and credits_attempted));
create table if not exists public.academic_teaching_unit_results(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),teaching_unit_id uuid not null references public.academic_teaching_units(id),semester_id uuid not null references public.academic_semesters(id),average_score numeric(7,2) not null check(average_score between 0 and 100),credits_attempted numeric(7,2) not null,credits_earned numeric(7,2) not null,status public.academic_unit_result_status not null,compensated boolean not null default false,workflow_status public.academic_result_workflow_status not null default 'CALCULATED',validated_by uuid references public.profiles(id),validated_at timestamptz,updated_at timestamptz not null default now(),unique(student_id,teaching_unit_id,semester_id),check(credits_earned between 0 and credits_attempted));
create table if not exists public.academic_semester_results(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),semester_id uuid not null references public.academic_semesters(id),academic_year_id uuid not null references public.academic_years(id),program_id uuid not null references public.academic_programs(id),program_version_id uuid not null references public.academic_program_versions(id),average_score numeric(7,2) not null check(average_score between 0 and 100),credits_attempted numeric(7,2) not null,credits_earned numeric(7,2) not null,semester_status public.academic_semester_result_status not null default 'PENDING_JURY',workflow_status public.academic_result_workflow_status not null default 'CALCULATED',jury_decision_id uuid,calculation_version integer not null default 1,calculated_by uuid references public.profiles(id),calculated_at timestamptz not null default now(),submitted_by uuid references public.profiles(id),submitted_at timestamptz,validated_by uuid references public.profiles(id),validated_at timestamptz,updated_at timestamptz not null default now(),unique(student_id,semester_id),check(credits_earned between 0 and credits_attempted));
create table if not exists public.academic_resit_eligibility(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),course_id uuid not null references public.academic_courses(id),semester_id uuid not null references public.academic_semesters(id),course_result_id uuid not null references public.academic_course_results(id),status public.academic_resit_status not null,eligibility_reason text not null,eligible_from date,eligible_until date,decided_by uuid references public.profiles(id),decided_at timestamptz not null default now(),unique(student_id,course_id,semester_id));
create table if not exists public.academic_credit_ledger(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),student_id uuid not null references public.academic_students(id),program_id uuid not null references public.academic_programs(id),academic_year_id uuid not null references public.academic_years(id),semester_id uuid references public.academic_semesters(id),level public.academic_credit_level not null,source_entity_id uuid not null,credits_attempted numeric(7,2) not null,credits_earned numeric(7,2) not null,posted_by uuid references public.profiles(id),posted_at timestamptz not null default now(),reason text not null,unique(student_id,level,source_entity_id),check(credits_earned between 0 and credits_attempted));
create table if not exists public.academic_result_history(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),entity_type text not null,entity_id uuid not null,student_id uuid not null references public.academic_students(id),old_workflow_status public.academic_result_workflow_status,new_workflow_status public.academic_result_workflow_status,old_result_status text,new_result_status text,old_score numeric(7,2),new_score numeric(7,2),reason text not null,changed_by uuid references public.profiles(id),changed_at timestamptz not null default now());

create index if not exists academic_course_results_student_idx on public.academic_course_results(student_id,semester_id,result_status);
create index if not exists academic_unit_results_student_idx on public.academic_teaching_unit_results(student_id,semester_id,status);
create index if not exists academic_semester_results_program_idx on public.academic_semester_results(program_id,semester_id,semester_status);
create index if not exists academic_credit_ledger_student_idx on public.academic_credit_ledger(student_id,academic_year_id,level);
create index if not exists academic_result_history_entity_idx on public.academic_result_history(entity_type,entity_id,changed_at desc);

insert into public.academic_role_permissions(role,permission_code,description_fr,description_en) values
('STUDENT','result.self.read','Consulter ses resultats valides','Read own validated results'),
('INSTRUCTOR','result.read','Consulter les resultats de ses cours','Read assigned course results'),('INSTRUCTOR','result.calculate','Calculer les resultats de ses cours','Calculate assigned course results'),
('COURSE_COORDINATOR','result.read','Consulter les resultats','Read results'),('COURSE_COORDINATOR','result.calculate','Calculer les resultats','Calculate results'),
('UNIT_COORDINATOR','result.read','Consulter les resultats des UE','Read unit results'),('UNIT_COORDINATOR','result.calculate','Calculer les resultats des UE','Calculate unit results'),
('PROGRAM_COORDINATOR','result.read','Consulter les resultats du programme','Read program results'),('PROGRAM_COORDINATOR','result.calculate','Calculer les resultats du programme','Calculate program results'),('PROGRAM_COORDINATOR','result.validate','Valider les resultats du programme','Validate program results'),
('ACADEMIC_SECRETARY','result.read','Consulter les resultats academiques','Read academic results'),
('ACADEMIC_ADMIN','result.read','Consulter tous les resultats','Read all results'),('ACADEMIC_ADMIN','result.calculate','Calculer tous les resultats','Calculate all results'),('ACADEMIC_ADMIN','result.validate','Valider les resultats','Validate results'),
('SUPER_ADMIN','result.read','Consulter tous les resultats','Read all results'),('SUPER_ADMIN','result.calculate','Calculer tous les resultats','Calculate all results'),('SUPER_ADMIN','result.validate','Valider tous les resultats','Validate all results')
on conflict(role,permission_code) do update set description_fr=excluded.description_fr,description_en=excluded.description_en;

create or replace function public.academic_grade_letter(p_score numeric) returns text language sql immutable as $$ select case when p_score>=90 then 'A+' when p_score>=80 then 'A' when p_score>=75 then 'B+' when p_score>=70 then 'B' when p_score>=65 then 'C+' when p_score>=60 then 'C' when p_score>=55 then 'D+' when p_score>=50 then 'D' else 'F' end $$;

create or replace function public.academic_calculate_student_semester_results(p_student_id uuid,p_semester_id uuid,p_reason text) returns public.academic_semester_results language plpgsql security definer set search_path=public as $$
declare sm public.academic_semesters;e record;old public.academic_course_results;cr public.academic_course_results;w numeric;regular numeric;ca numeric;exam numeric;rw numeric;resit numeric;cap numeric;score numeric;cs public.academic_course_result_status;earned numeric;u record;ua numeric;ut numeric;ue numeric;uf integer;us public.academic_unit_result_status;sa numeric;st numeric;se numeric;sr integer;sf integer;ss public.academic_semester_result_status;r public.academic_semester_results;found_enrollment boolean:=false;
begin
 select * into sm from public.academic_semesters where id=p_semester_id;if sm.id is null then raise exception 'Semester not found';end if;
 if not public.academic_has_program_scope(sm.organization_id,sm.program_id,'result.calculate') then raise exception 'Result calculation permission required';end if;
 for e in select ce.*,c.credits,c.coefficient,c.minimum_pass_mark,c.resit_allowed from public.academic_course_enrollments ce join public.academic_courses c on c.id=ce.course_id where ce.student_id=p_student_id and ce.semester_id=p_semester_id and ce.status='ACTIVE' loop
  found_enrollment:=true;
  select coalesce(sum(a.weight),0),coalesce(sum(g.normalized_score*a.weight)/100,0) into w,regular from public.academic_assessments a left join public.academic_grades g on g.assessment_id=a.id and g.student_id=p_student_id and g.status='PUBLISHED' where a.course_id=e.course_id and a.semester_id=p_semester_id and not a.is_resit and a.status not in('CANCELLED','ARCHIVED');
  if w<>100 then raise exception 'Assessment weights must total 100 for course % (current: %)',e.course_id,w;end if;
  if exists(select 1 from public.academic_assessments a where a.course_id=e.course_id and a.semester_id=p_semester_id and not a.is_resit and a.status not in('CANCELLED','ARCHIVED') and not exists(select 1 from public.academic_grades g where g.assessment_id=a.id and g.student_id=p_student_id and g.status='PUBLISHED')) then raise exception 'All regular grades must be published';end if;
  select coalesce(sum(g.normalized_score*a.weight)/nullif(sum(a.weight),0),0) into ca from public.academic_assessments a join public.academic_grades g on g.assessment_id=a.id and g.student_id=p_student_id and g.status='PUBLISHED' where a.course_id=e.course_id and a.semester_id=p_semester_id and not a.is_resit and a.assessment_type<>'FINAL_EXAM';
  select coalesce(sum(g.normalized_score*a.weight)/nullif(sum(a.weight),0),0) into exam from public.academic_assessments a join public.academic_grades g on g.assessment_id=a.id and g.student_id=p_student_id and g.status='PUBLISHED' where a.course_id=e.course_id and a.semester_id=p_semester_id and not a.is_resit and a.assessment_type='FINAL_EXAM';
  select coalesce(sum(a.weight),0),coalesce(sum(g.normalized_score*a.weight)/nullif(sum(a.weight),0),0) into rw,resit from public.academic_assessments a join public.academic_grades g on g.assessment_id=a.id and g.student_id=p_student_id and g.status='PUBLISHED' where a.course_id=e.course_id and a.semester_id=p_semester_id and a.is_resit;
  select coalesce(max(value_numeric),e.minimum_pass_mark) into cap from public.academic_rules where program_version_id=sm.program_version_id and rule_code='RESIT_SCORE_CAP' and status='APPROVED' and effective_from<=current_date and(effective_to is null or effective_to>=current_date);
  score:=round(case when rw>0 then greatest(regular,least(resit,cap)) else regular end,2);
  if score>=e.minimum_pass_mark then cs:='PASSED';earned:=e.credits;elsif e.resit_allowed and rw=0 then cs:='RESIT_REQUIRED';earned:=0;else cs:='FAILED';earned:=0;end if;
  select * into old from public.academic_course_results where student_id=p_student_id and course_id=e.course_id and semester_id=p_semester_id for update;if old.workflow_status='VALIDATED' then raise exception 'Validated results cannot be recalculated';end if;
  insert into public.academic_course_results(organization_id,student_id,course_id,semester_id,course_enrollment_id,continuous_assessment_score,final_exam_score,resit_score,final_score,grade_letter,credits_attempted,credits_earned,result_status,calculation_version,calculated_by) values(sm.organization_id,p_student_id,e.course_id,p_semester_id,e.id,round(ca,2),round(exam,2),case when rw>0 then round(resit,2) end,score,public.academic_grade_letter(score),e.credits,earned,cs,coalesce(old.calculation_version,0)+1,auth.uid()) on conflict(student_id,course_id,semester_id) do update set continuous_assessment_score=excluded.continuous_assessment_score,final_exam_score=excluded.final_exam_score,resit_score=excluded.resit_score,final_score=excluded.final_score,grade_letter=excluded.grade_letter,credits_attempted=excluded.credits_attempted,credits_earned=excluded.credits_earned,result_status=excluded.result_status,workflow_status='CALCULATED',calculation_version=academic_course_results.calculation_version+1,calculated_by=auth.uid(),calculated_at=now(),updated_at=now() returning * into cr;
  insert into public.academic_resit_eligibility(organization_id,student_id,course_id,semester_id,course_result_id,status,eligibility_reason,eligible_from,eligible_until,decided_by) values(sm.organization_id,p_student_id,e.course_id,p_semester_id,cr.id,case when cs='RESIT_REQUIRED' then 'ELIGIBLE'::public.academic_resit_status when rw>0 then 'COMPLETED'::public.academic_resit_status else 'NOT_ELIGIBLE'::public.academic_resit_status end,case when cs='RESIT_REQUIRED' then 'Below pass mark; resit allowed' when rw>0 then 'Published resit included' else 'No resit required' end,sm.resit_start_date,sm.resit_end_date,auth.uid()) on conflict(student_id,course_id,semester_id) do update set course_result_id=excluded.course_result_id,status=excluded.status,eligibility_reason=excluded.eligibility_reason,eligible_from=excluded.eligible_from,eligible_until=excluded.eligible_until,decided_by=auth.uid(),decided_at=now();
 end loop;
 if not found_enrollment then raise exception 'No active course enrollment found';end if;
 for u in select distinct tu.* from public.academic_teaching_units tu join public.academic_courses c on c.teaching_unit_id=tu.id join public.academic_course_results cr0 on cr0.course_id=c.id where cr0.student_id=p_student_id and cr0.semester_id=p_semester_id loop
  select round(sum(x.final_score*c.coefficient)/nullif(sum(c.coefficient),0),2),sum(x.credits_attempted),sum(x.credits_earned),count(*) filter(where x.result_status<>'PASSED') into ua,ut,ue,uf from public.academic_course_results x join public.academic_courses c on c.id=x.course_id where x.student_id=p_student_id and x.semester_id=p_semester_id and c.teaching_unit_id=u.id;
  if ua>=u.minimum_pass_mark and uf=0 then us:='VALIDATED';elsif ua>=u.minimum_pass_mark and u.compensable then us:='COMPENSATED';ue:=ut;elsif ue>0 then us:='PARTIALLY_VALIDATED';else us:='FAILED';end if;
  insert into public.academic_teaching_unit_results(organization_id,student_id,teaching_unit_id,semester_id,average_score,credits_attempted,credits_earned,status,compensated) values(sm.organization_id,p_student_id,u.id,p_semester_id,ua,ut,ue,us,us='COMPENSATED') on conflict(student_id,teaching_unit_id,semester_id) do update set average_score=excluded.average_score,credits_attempted=excluded.credits_attempted,credits_earned=excluded.credits_earned,status=excluded.status,compensated=excluded.compensated,workflow_status='CALCULATED',validated_by=null,validated_at=null,updated_at=now();
 end loop;
 select round(sum(x.final_score*c.coefficient)/nullif(sum(c.coefficient),0),2),sum(x.credits_attempted),sum(x.credits_earned),count(*) filter(where x.result_status='RESIT_REQUIRED'),count(*) filter(where x.result_status='FAILED') into sa,st,se,sr,sf from public.academic_course_results x join public.academic_courses c on c.id=x.course_id where x.student_id=p_student_id and x.semester_id=p_semester_id;
 if sr>0 then ss:='RESIT_REQUIRED';elsif sf>0 and se=0 then ss:='FAILED';elsif sf>0 or se<st then ss:='PARTIALLY_VALIDATED';else ss:='PENDING_JURY';end if;
 insert into public.academic_semester_results(organization_id,student_id,semester_id,academic_year_id,program_id,program_version_id,average_score,credits_attempted,credits_earned,semester_status,calculated_by) values(sm.organization_id,p_student_id,p_semester_id,sm.academic_year_id,sm.program_id,sm.program_version_id,sa,st,se,ss,auth.uid()) on conflict(student_id,semester_id) do update set average_score=excluded.average_score,credits_attempted=excluded.credits_attempted,credits_earned=excluded.credits_earned,semester_status=excluded.semester_status,workflow_status='CALCULATED',calculation_version=academic_semester_results.calculation_version+1,calculated_by=auth.uid(),calculated_at=now(),submitted_by=null,submitted_at=null,validated_by=null,validated_at=null,updated_at=now() returning * into r;
 insert into public.academic_result_history(organization_id,entity_type,entity_id,student_id,new_workflow_status,new_result_status,new_score,reason,changed_by) values(sm.organization_id,'SEMESTER_RESULT',r.id,p_student_id,'CALCULATED',r.semester_status::text,r.average_score,coalesce(nullif(trim(p_reason),''),'Deterministic recalculation'),auth.uid());return r;
end $$;

create or replace function public.academic_transition_semester_result(p_result_id uuid,p_status public.academic_result_workflow_status,p_reason text) returns public.academic_semester_results language plpgsql security definer set search_path=public as $$
declare r public.academic_semester_results;old public.academic_result_workflow_status;begin select * into r from public.academic_semester_results where id=p_result_id for update;if r.id is null then raise exception 'Result not found';end if;old:=r.workflow_status;
if not public.academic_has_program_scope(r.organization_id,r.program_id,case when p_status='VALIDATED' then 'result.validate' else 'result.calculate' end) then raise exception 'Result workflow permission required';end if;
if not((old='CALCULATED' and p_status='SUBMITTED')or(old='STALE' and p_status='CALCULATED')or(old='SUBMITTED' and p_status='VALIDATED'))then raise exception 'Invalid transition: % -> %',old,p_status;end if;
update public.academic_semester_results set workflow_status=p_status,semester_status=case when p_status='VALIDATED' and semester_status='PENDING_JURY' then 'VALIDATED' else semester_status end,submitted_by=case when p_status='SUBMITTED' then auth.uid() else submitted_by end,submitted_at=case when p_status='SUBMITTED' then now() else submitted_at end,validated_by=case when p_status='VALIDATED' then auth.uid() else validated_by end,validated_at=case when p_status='VALIDATED' then now() else validated_at end,updated_at=now() where id=r.id returning * into r;
update public.academic_course_results set workflow_status=p_status,submitted_by=case when p_status='SUBMITTED' then auth.uid() else submitted_by end,submitted_at=case when p_status='SUBMITTED' then now() else submitted_at end,validated_by=case when p_status='VALIDATED' then auth.uid() else validated_by end,validated_at=case when p_status='VALIDATED' then now() else validated_at end where student_id=r.student_id and semester_id=r.semester_id;
update public.academic_teaching_unit_results set workflow_status=p_status,validated_by=case when p_status='VALIDATED' then auth.uid() else validated_by end,validated_at=case when p_status='VALIDATED' then now() else validated_at end where student_id=r.student_id and semester_id=r.semester_id;
if p_status='VALIDATED' then
 insert into public.academic_credit_ledger(organization_id,student_id,program_id,academic_year_id,semester_id,level,source_entity_id,credits_attempted,credits_earned,posted_by,reason) select organization_id,student_id,r.program_id,r.academic_year_id,semester_id,'COURSE',id,credits_attempted,credits_earned,auth.uid(),p_reason from public.academic_course_results where student_id=r.student_id and semester_id=r.semester_id on conflict do nothing;
 insert into public.academic_credit_ledger(organization_id,student_id,program_id,academic_year_id,semester_id,level,source_entity_id,credits_attempted,credits_earned,posted_by,reason) select organization_id,student_id,r.program_id,r.academic_year_id,semester_id,'TEACHING_UNIT',id,credits_attempted,credits_earned,auth.uid(),p_reason from public.academic_teaching_unit_results where student_id=r.student_id and semester_id=r.semester_id on conflict do nothing;
 insert into public.academic_credit_ledger(organization_id,student_id,program_id,academic_year_id,semester_id,level,source_entity_id,credits_attempted,credits_earned,posted_by,reason) values(r.organization_id,r.student_id,r.program_id,r.academic_year_id,r.semester_id,'SEMESTER',r.id,r.credits_attempted,r.credits_earned,auth.uid(),p_reason) on conflict do nothing;
end if;
insert into public.academic_result_history(organization_id,entity_type,entity_id,student_id,old_workflow_status,new_workflow_status,old_result_status,new_result_status,old_score,new_score,reason,changed_by) values(r.organization_id,'SEMESTER_RESULT',r.id,r.student_id,old,p_status,r.semester_status::text,r.semester_status::text,r.average_score,r.average_score,coalesce(nullif(trim(p_reason),''),'Workflow transition'),auth.uid());return r;end $$;

create or replace function public.academic_mark_results_stale() returns trigger language plpgsql security definer set search_path=public as $$ declare a public.academic_assessments;begin if old.status='PUBLISHED' and row(old.raw_score,old.status) is distinct from row(new.raw_score,new.status) then select * into a from public.academic_assessments where id=new.assessment_id;update public.academic_course_results set workflow_status='STALE' where student_id=new.student_id and course_id=a.course_id and semester_id=a.semester_id;update public.academic_teaching_unit_results set workflow_status='STALE' where student_id=new.student_id and semester_id=a.semester_id;update public.academic_semester_results set workflow_status='STALE' where student_id=new.student_id and semester_id=a.semester_id;end if;return new;end $$;
drop trigger if exists academic_grade_result_stale on public.academic_grades;create trigger academic_grade_result_stale after update on public.academic_grades for each row execute function public.academic_mark_results_stale();

do $$ declare t text;begin foreach t in array array['academic_course_results','academic_teaching_unit_results','academic_semester_results','academic_resit_eligibility','academic_credit_ledger','academic_result_history'] loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists %I on public.%I','academic results staff read',t);end loop;end $$;
create policy "academic results staff read" on public.academic_course_results for select to authenticated using(exists(select 1 from public.academic_semesters sm where sm.id=semester_id and public.academic_has_program_scope(organization_id,sm.program_id,'result.read')));
create policy "academic results staff read" on public.academic_teaching_unit_results for select to authenticated using(exists(select 1 from public.academic_semesters sm where sm.id=semester_id and public.academic_has_program_scope(organization_id,sm.program_id,'result.read')));
create policy "academic results staff read" on public.academic_semester_results for select to authenticated using(public.academic_has_program_scope(organization_id,program_id,'result.read'));
create policy "academic results staff read" on public.academic_resit_eligibility for select to authenticated using(exists(select 1 from public.academic_semesters sm where sm.id=semester_id and public.academic_has_program_scope(organization_id,sm.program_id,'result.read')));
create policy "academic results staff read" on public.academic_credit_ledger for select to authenticated using(public.academic_has_program_scope(organization_id,program_id,'result.read'));
create policy "academic results staff read" on public.academic_result_history for select to authenticated using(public.academic_has_permission(organization_id,'result.validate'));
drop policy if exists "academic own course results" on public.academic_course_results;create policy "academic own course results" on public.academic_course_results for select to authenticated using(workflow_status='VALIDATED' and exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
drop policy if exists "academic own unit results" on public.academic_teaching_unit_results;create policy "academic own unit results" on public.academic_teaching_unit_results for select to authenticated using(workflow_status='VALIDATED' and exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
drop policy if exists "academic own semester results" on public.academic_semester_results;create policy "academic own semester results" on public.academic_semester_results for select to authenticated using(workflow_status='VALIDATED' and exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
drop policy if exists "academic own resits" on public.academic_resit_eligibility;create policy "academic own resits" on public.academic_resit_eligibility for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
drop policy if exists "academic own credits" on public.academic_credit_ledger;create policy "academic own credits" on public.academic_credit_ledger for select to authenticated using(exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));
revoke all on function public.academic_calculate_student_semester_results(uuid,uuid,text) from public;revoke all on function public.academic_transition_semester_result(uuid,public.academic_result_workflow_status,text) from public;
grant execute on function public.academic_calculate_student_semester_results(uuid,uuid,text) to authenticated;grant execute on function public.academic_transition_semester_result(uuid,public.academic_result_workflow_status,text) to authenticated;
comment on table public.academic_credit_ledger is 'Detailed credit ledger: course, unit, semester, year and program totals remain reconstructible.';
-- Progression proposals are prepared in Lot 7 and remain pending until the jury module records an official decision.
do $$ begin create type public.academic_progression_decision as enum ('PROGRESS','CONDITIONAL','REPEAT','SUSPEND','WITHDRAW','GRADUATE','PENDING_JURY'); exception when duplicate_object then null; end $$;
create table if not exists public.academic_progression(
 id uuid primary key default gen_random_uuid(),
 organization_id uuid not null references public.organizations(id) on delete restrict,
 student_id uuid not null references public.academic_students(id) on delete restrict,
 program_id uuid not null references public.academic_programs(id) on delete restrict,
 academic_year_from_id uuid not null references public.academic_years(id) on delete restrict,
 academic_year_to_id uuid references public.academic_years(id) on delete restrict,
 program_year_from smallint not null check(program_year_from>0),
 program_year_to smallint check(program_year_to>0),
 credits_attempted numeric(7,2) not null default 0,
 credits_earned numeric(7,2) not null default 0,
 proposed_decision public.academic_progression_decision not null default 'PENDING_JURY',
 official_decision public.academic_progression_decision,
 decision_reason text,
 jury_decision_id uuid,
 workflow_status public.academic_result_workflow_status not null default 'CALCULATED',
 calculated_by uuid references public.profiles(id) on delete set null,
 calculated_at timestamptz not null default now(),
 validated_by uuid references public.profiles(id) on delete set null,
 validated_at timestamptz,
 unique(student_id,academic_year_from_id)
);
alter table public.academic_progression enable row level security;
drop policy if exists "academic progression staff read" on public.academic_progression;
create policy "academic progression staff read" on public.academic_progression for select to authenticated using(public.academic_has_program_scope(organization_id,program_id,'result.read'));
drop policy if exists "academic own progression" on public.academic_progression;
create policy "academic own progression" on public.academic_progression for select to authenticated using(workflow_status='VALIDATED' and exists(select 1 from public.academic_students s where s.id=student_id and s.user_id=auth.uid()));

create or replace view public.academic_credit_totals with (security_invoker=true) as
 select organization_id,student_id,program_id,academic_year_id,semester_id,'SEMESTER'::text as total_level,sum(credits_attempted) as credits_attempted,sum(credits_earned) as credits_earned
 from public.academic_credit_ledger where level='COURSE' group by organization_id,student_id,program_id,academic_year_id,semester_id
 union all
 select organization_id,student_id,program_id,academic_year_id,null::uuid,'ACADEMIC_YEAR',sum(credits_attempted),sum(credits_earned)
 from public.academic_credit_ledger where level='COURSE' group by organization_id,student_id,program_id,academic_year_id
 union all
 select organization_id,student_id,program_id,null::uuid,null::uuid,'PROGRAM',sum(credits_attempted),sum(credits_earned)
 from public.academic_credit_ledger where level='COURSE' group by organization_id,student_id,program_id;
grant select on public.academic_credit_totals to authenticated;
comment on table public.academic_progression is 'Auditable progression proposal; official decisions are reserved for the jury workflow.';
comment on view public.academic_credit_totals is 'Derived semester, academic-year and program totals from course-level validated credit entries.';